name: CI - gz-physics integration

on:
  push:
    branches: [ main, master, develop ]
  pull_request:
    branches: [ main, master, develop ]

jobs:
  test-gz-physics:
    runs-on: ubuntu-22.04
    strategy:
      fail-fast: false
      matrix:
        # Test against the latest stable release of gz-physics
        # As of late 2023/early 2024, gz-physics7 is the current stable series.
        # We use the 'gz-physics7' package name which pulls the latest patch.
        gz-physics-version: [gz-physics7]

    steps:
      - name: Checkout dartsim/dart
        uses: actions/checkout@v4

      - name: Set up Python
        uses: actions/setup-python@v5
        with:
          python-version: '3.10'

      - name: Install system dependencies
        run: |
          sudo apt-get update
          sudo apt-get install -y \
            build-essential \
            cmake \
            git \
            libboost-all-dev \
            libeigen3-dev \
            libtinyxml2-dev \
            liburdfdom-dev \
            libsdformat13-dev \
            ${{ matrix.gz-physics-version }} \
            lib${{ matrix.gz-physics-version }}-dev

      - name: Configure CMake
        run: |
          mkdir -p build
          cd build
          cmake .. \
            -DCMAKE_BUILD_TYPE=Release \
            -DDART_BUILD_TESTS=ON \
            -DDART_BUILD_EXAMPLES=OFF \
            -DDART_BUILD_TOOLS=OFF \
            -DDART_BUILD_TUTORIALS=OFF \
            -DDART_ENABLE_GZ_PHYSICS=ON

      - name: Build
        run: |
          cd build
          cmake --build . -j$(nproc)

      - name: Run DART Tests
        run: |
          cd build
          ctest --output-on-failure -j$(nproc)

      - name: Build and Run gz-physics DART Plugin Tests
        run: |
          # Find the gz-physics plugin directory for dart
          # The plugin is usually built as part of gz-physics, but we need to ensure
          # the dart plugin specifically is tested if available in the dev package.
          # Alternatively, we can compile a small test program that uses gz-physics dart plugin.

          # Check if the gz-physics dart plugin library exists
          PLUGIN_LIB=$(find /usr/lib -name "libgz-physics-dart*" -type f 2>/dev/null | head -n 1)

          if [ -z "$PLUGIN_LIB" ]; then
            echo "Warning: gz-physics dart plugin library not found in standard paths. Skipping specific plugin integration test."
            exit 0
          fi

          echo "Found plugin library: $PLUGIN_LIB"

          # Create a simple test to ensure the plugin can be loaded and basic operations work
          mkdir -p test_gz_integration
          cd test_gz_integration

          cat > CMakeLists.txt << EOF
          cmake_minimum_required(VERSION 3.16)
          project(gz_physics_dart_test)

          find_package(gz-physics7 REQUIRED)
          find_package(dart REQUIRED)

          add_executable(test_dart_plugin test_dart_plugin.cpp)
          target_link_libraries(test_dart_plugin PRIVATE 
            gz-physics7::core 
            dart::dart
          )
          EOF

          cat > test_dart_plugin.cpp << 'EOF'
          #include <gz/physics/GetFeatures.h>
          #include <gz/physics/FindFeature.h>
          #include <gz/physics/FeatureList.h>
          #include <gz/physics/World.hh>
          #include <gz/physics/Model.hh>
          #include <gz/physics/Link.hh>
          #include <gz/physics/Shape.hh>
          #include <iostream>

          // Define the features we want to test
          using TestFeatures = gz::physics::FeatureList<
              gz::physics::World,
              gz::physics::Model,
              gz::physics::Link,
              gz::physics::Shape
          >;

          int main() {
              try {
                  // Get the dart plugin
                  auto plugin = gz::physics::findFeatureMap<TestFeatures>("dart");

                  if (!plugin) {
                      std::cerr << "Failed to find dart plugin in gz-physics" << std::endl;
                      return 1;
                  }

                  // Create a world
                  auto world = plugin->CreateWorld();
                  if (!world) {
                      std::cerr << "Failed to create world" << std::endl;
                      return 1;
                  }

                  // Create a model
                  auto model = world->CreateModel("test_model");
                  if (!model) {
                      std::cerr << "Failed to create model" << std::endl;
                      return 1;
                  }

                  // Create a link
                  auto link = model->CreateLink("test_link");
                  if (!link) {
                      std::cerr << "Failed to create link" << std::endl;
                      return 1;
                  }

                  // Create a shape (box)
                  auto shape = link->CreateBoxShape(gz::math::Vector3d(1, 1, 1));
                  if (!shape) {
                      std::cerr << "Failed to create shape" << std::endl;
                      return 1;
                  }

                  std::cout << "Successfully created gz-physics dart world, model, link, and shape." << std::endl;
                  return 0;
              } catch (const std::exception& e) {
                  std::cerr << "Exception: " << e.what() << std::endl;
                  return 1;
              }
          }
          EOF

          mkdir -p build
          cd build
          cmake ..
          make -j$(nproc)
          ./test_dart_plugin
```

